    # Use a classic DP with only two rows to save memory
    if len(a) < len(b):
        # Ensure that b is the shorter one to reduce space
        a, b = b, a
    # Now len(a) >= len(b)
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i] + [0] * len(b)
