from fractions import Fraction

def solve(mat):
    # Empty matrix case
    if not mat:
        return 1
    n = len(mat)
    # Verify square
    for row in mat:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Convert to Fractions for exact arithmetic
    A = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # Find pivot
        pivot = i
        while pivot < n and A[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            # swap rows
            A[i], A[pivot] = A[pivot], A[i]
            sign *= -1
        pivot_val = A[i][i]
        det *= pivot_val
        # Normalize row i (optional) but we keep exact
        for j in range(i+1, n):
            factor = A[j][i] / pivot_val
            # Row_j = Row_j - factor * Row_i
            for k in range(i, n):
                A[j][k] -= factor * A[i][k]
    det *= sign
    # det should be integer
    return int(det)

