    """Return length of longest substring without repeating characters.
    If *s* is not a string, it is converted to ``str``; an empty input yields 0.
    Uses a sliding window that tracks the last seen index of each character.
    """
    # Ensure we are working with a string representation
    if not isinstance(s, str):
        try:
            s = str(s)
        except Exception:
            return 0
    last_index = {}
    max_len = 0
    start = 0
    for i, ch in enumerate(s):
        prev = last_index.get(ch, -1)
        if prev >= start:
            start = prev + 1
        last_index[ch] = i
        # i - start + 1 is the length of current window
        if i - start + 1 > max_len:
            max_len = i - start + 1
    return max_len

