def solve(coins, amount):
    """Return the minimum number of coins needed to make up the amount.
    Unlimited supply of each coin value. Return -1 if impossible.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Dynamic programming: dp[i] = min coins for amount i
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

