    """Simplify a Unix-style path.
    Handles both absolute and relative paths.
    - Collapse multiple '/' characters.
    - Resolve '.' (current directory) and '..' (parent directory).
    - Preserve leading '/' only if the original path is absolute.
    - Remove trailing '/' unless the result is root '/' or empty for relative.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # for relative paths, keep leading '..'
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(part)
    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
    else:
        return '/'.join(stack)
"}

