def solve(intervals):
    """Merge overlapping or touching intervals.
    Handles intervals where start may be greater than end by normalising them.
    Returns a list of merged intervals sorted by start.
    """
    if not intervals:
        return []
    # Normalise intervals to ensure start <= end and copy to new list
    norm = []
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError('Each interval must have exactly two elements')
        s, e = iv[0], iv[1]
        if s > e:
            s, e = e, s
        norm.append([s, e])
    # Sort by start then end
    norm.sort(key=lambda x: (x[0], x[1]))
    merged = []
    for s, e in norm:
        if not merged:
            merged.append([s, e])
        else:
            last = merged[-1]
            # If current interval starts after the last merged interval ends, no overlap/touch
            if s > last[1]:
                merged.append([s, e])
            else:
                # Overlap or touching: extend the last interval's end if needed
                if e > last[1]:
                    last[1] = e
    return merged

