    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def dfs(r, c):
        stack = [(r,c)]
        while stack:
            x,y = stack.pop()
            if x<0 or x>=rows:
                continue
            if y<0 or y>=len(grid[x]):
                continue
            if visited[x][y] or grid[x][y]==0:
                continue
            visited[x][y]=True
            stack.append((x+1,y))
            stack.append((x-1,y))
            stack.append((x,y+1))
            stack.append((x,y-1))
    count=0
    for i in range(rows):
