def solve(n, b):
    """Convert integer n to a string in base b (2 <= b <= 36).
    Uses digits 0-9 then lowercase a-z. Handles negative numbers with leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError("Base out of range")
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = ''
    if n < 0:
        sign = '-'
        n = -n
    res = []
    while n:
        n, r = divmod(n, b)
        res.append(digits[r])
