    If n == 0 return -1. If n == 1 return 0. Return -1 when target unreachable.
    """
    if n <= 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        # Validate nodes and weight (allow zero weight)
        if not (0 <= a < n and 0 <= b < n):
            continue
        if w < 0:
            continue  # ignore negative weights as per positive weight guarantee
        adj[a].append((b, w))
        adj[b].append((a, w))
    import heapq
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1 if dist[n-1] == INF else dist[n-1]

